/* Malta Driving Master 45.8.38.25.2 — School Evidence standalone page logic */
(function(){'use strict';const VERSION='45.8.38.25.2',$=id=>document.getElementById(id);function parse(v){try{return v?JSON.parse(v):null}catch(_){return null}}function settings(){return parse(localStorage.getItem('mdm-v1-settings'))||{}}function lang(){const l=String(settings().lang||'en').toLowerCase();return ['it','en','mt'].includes(l)?l:'en'}function t(it,en,mt){return lang()==='it'?it:lang()==='mt'?mt:en}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function saveLang(l){const s=settings();s.lang=l;localStorage.setItem('mdm-v1-settings',JSON.stringify(s));localize();renderEmpty()}function session(){for(const k of ['mdm_auth_session_v4410','mdm_auth_session_v1','mdm-auth-session']){const s=parse(localStorage.getItem(k));if((s?.accessToken||s?.access_token)&&s?.user?.id)return s}return{}}function token(){const s=session();return s.accessToken||s.access_token||''}function cfg(){const c=window.MDM_BACKEND_CONFIG||{};const endpoint=c.endpoint||c.url||c.supabaseUrl,key=c.publishableKey||c.anonKey||c.key;if(!endpoint||!key)throw new Error('backend_config_unavailable');return{endpoint:String(endpoint).replace(/\/$/,''),key:String(key)}}async function rpc(name,payload){const c=cfg(),tk=token();if(!tk)throw new Error('authentication_required');const r=await fetch(c.endpoint+'/rest/v1/rpc/'+name,{method:'POST',headers:{'Content-Type':'application/json','apikey':c.key,'Authorization':'Bearer '+tk},body:JSON.stringify(payload||{}),cache:'no-store'});const tx=await r.text();let d={};try{d=tx?JSON.parse(tx):{}}catch(_){}if(Array.isArray(d))d=d[0]||{};if(!r.ok)throw new Error(String(d?.message||d?.error||('http_'+r.status)));return d||{}}function goBack(){if(history.length>1){history.back();return}location.replace('./')}function localize(){document.documentElement.lang=lang();$('langBtn').textContent=lang().toUpperCase();$('pageTitle').textContent='🔄 '+t('Evidenze studenti','Student Evidence','Evidenza tal-istudenti');$('pageSub').textContent=t('Missioni, prove e verifica umana.','Missions, evidence and human review.','Missjonijiet, evidenza u verifika umana.');$('assignTitle').textContent=t('Assegna missione di verifica','Assign verification mission','Assenja missjoni ta’ verifika');$('studentLabel').textContent=t('Studente','Student','Student');$('typeLabel').textContent=t('Tipo missione','Mission type','Tip ta’ missjoni');$('typeVerification').textContent=t('Verifica','Verification','Verifika');$('typePractical').textContent=t('Verifica pratica','Practical verification','Verifika prattika');$('typeTheory').textContent=t('Recupero teoria','Theory recovery','Irkupru tat-teorija');$('packLabel').textContent=t('Licenza','Licence','Liċenzja');$('packB').textContent=t('B · Auto','B · Car','B · Karozza');$('packA').textContent=t('A · Moto','A · Motorcycle','A · Mutur');$('packCCE').textContent=t('C/CE · Camion','C/CE · Truck','C/CE · Trakk');$('packD').textContent=t('D · Bus','D · Bus','D · Xarabank');$('competenceLabel').textContent=t('Competenza da verificare','Competence to verify','Ħila għall-verifika');$('competenceChoose').textContent=t('Seleziona competenza','Select competence','Agħżel ħila');$('competenceRisk').textContent=t('Rischi, condizioni e attenzione','Risk, conditions and attention','Riskji, kundizzjonijiet u attenzjoni');$('competenceObservation').textContent=t('Osservazione e specchi','Observation and mirrors','Osservazzjoni u mirja');$('competenceJunctions').textContent=t('Incroci e precedenza','Junctions and priority','Salib it-toroq u prijorità');$('competencePositioning').textContent=t('Posizionamento e corsia','Positioning and lane discipline','Pożizzjonament u korsija');$('competenceSpeed').textContent=t('Velocità e adattamento','Speed and adaptation','Veloċità u adattament');$('competenceControl').textContent=t('Controllo del veicolo','Vehicle control','Kontroll tal-vettura');$('competenceManoeuvres').textContent=t('Manovre','Manoeuvres','Manuvri');$('competenceVulnerable').textContent=t('Utenti vulnerabili','Vulnerable road users','Utenti vulnerabbli');$('objectiveLabel').textContent=t('Obiettivo','Objective','Għan');$('objective').placeholder=t('Descrivi ciò che deve essere verificato','Describe what must be verified','Iddeskrivi x’għandu jiġi vverifikat');$('assignBtn').textContent='＋ '+t('Assegna','Assign','Assenja');$('reviewTitle').textContent=t('Evidenze da verificare','Evidence awaiting review','Evidenza għar-reviżjoni');$('missionsTitle').textContent=t('Missioni recenti','Recent missions','Missjonijiet riċenti');$('foot').textContent=t('Solo verifica umana · Nessuna certificazione pratica automatica','Human review only · No automatic practical certification','Verifika umana biss · Ebda ċertifikazzjoni prattika awtomatika')}function errorText(e){const c=String(e||'').toLowerCase();if(c.includes('school_not_authorized'))return t('La scuola non è ancora autorizzata a usare il backend delle evidenze.','The school is not yet authorized to use the evidence backend.','L-iskola għadha mhix awtorizzata tuża l-backend tal-evidenza.');if(c.includes('authentication_required'))return t('Accesso richiesto. Rientra nell’account scuola.','Sign-in required. Sign in again with the school account.','Huwa meħtieġ id-dħul. Erġa’ idħol bil-kont tal-iskola.');return t('Backend evidenze temporaneamente non disponibile.','Evidence backend is temporarily unavailable.','Il-backend tal-evidenza temporanjament mhux disponibbli.')}function setStatus(x,k=''){ $('status').textContent=x;$('status').className='status'+(k?' '+k:'')}function renderEmpty(){$('reviewList').innerHTML='<p class="empty">—</p>';$('missionsList').innerHTML='<p class="empty">—</p>'}function renderStudents(a){const s=$('studentSelect');if(!a.length){s.innerHTML='<option>'+esc(t('Nessuno studente attivo','No active students','L-ebda student attiv'))+'</option>';s.disabled=true;$('assignBtn').disabled=true;return}s.innerHTML=a.map(x=>'<option value="'+esc(x.student_user_id)+'">'+esc(x.student_name||x.student_email||t('Studente','Student','Student'))+'</option>').join('');s.disabled=false;$('assignBtn').disabled=false}function mTitle(m){return m?.payload?.title||m?.payload?.objective||t('Missione','Mission','Missjoni')}function mStatus(s){const m={assigned:['Assegnata','Assigned','Assenjata'],evidence_submitted:['Prova inviata','Evidence submitted','Evidenza mibgħuta'],accepted:['Accettata','Accepted','Aċċettata'],revision_requested:['Nuova prova richiesta','Revision requested','Evidenza ġdida mitluba']},v=m[s];return v?t(v[0],v[1],v[2]):t('Stato non disponibile','Status unavailable','Status mhux disponibbli')}function renderMissions(a){$('missionsList').innerHTML=a.length?a.slice(0,20).map(m=>'<article class="item"><div class="item-head"><h3>'+esc(mTitle(m))+'</h3><span class="pill">'+esc(mStatus(m.status))+'</span></div><p>'+esc(m.student_evidence?.summary||t('Nessuna evidenza allegata.','No evidence attached.','L-ebda evidenza mehmuża.'))+'</p></article>').join(''):'<p class="empty">'+t('Nessuna missione.','No missions.','L-ebda missjoni.')+'</p>'}function renderReviews(a){const p=a.filter(m=>m.status==='evidence_submitted');$('reviewList').innerHTML=p.length?p.map(m=>'<article class="item" data-mid="'+esc(m.mission_id)+'"><div class="item-head"><h3>'+esc(mTitle(m))+'</h3><span class="pill">'+t('DA VERIFICARE','AWAITING REVIEW','GĦAR-REVIŻJONI')+'</span></div><p>'+esc(m.student_evidence?.summary||t('Evidenza ricevuta.','Evidence received.','Evidenza riċevuta.'))+'</p><div class="actions"><button class="btn" data-d="accepted">✓ '+t('Accetta','Accept','Aċċetta')+'</button><button class="btn secondary" data-d="revision_requested">↺ '+t('Richiedi nuova prova','Request new evidence','Itlob evidenza ġdida')+'</button></div></article>').join(''):'<p class="empty">'+t('Nessuna evidenza in attesa.','No evidence awaiting review.','L-ebda evidenza qed tistenna reviżjoni.')+'</p>';document.querySelectorAll('[data-d]').forEach(b=>b.onclick=async()=>{try{await rpc('mdm_school_review_mission_evidence',{p_mission_id:b.closest('[data-mid]').dataset.mid,p_decision:b.dataset.d,p_review:{human:true,source:'school-evidence-page',version:VERSION}});await load()}catch(e){setStatus('⚠️ '+errorText(e.message||e),'warn')}})}async function assign(){const st=$('studentSelect').value,o=$('objective').value.trim(),pack=$('packSelect').value,competence=$('competenceSelect').value,competenceText=$('competenceSelect').selectedOptions?.[0]?.textContent||'';if(!st||!o||!pack||!competence){setStatus(t('Seleziona studente, licenza, competenza e inserisci un obiettivo.','Select student, licence, competence and enter an objective.','Agħżel student, liċenzja, ħila u daħħal għan.'),'warn');return}try{await rpc('mdm_school_assign_evidence_mission',{p_student_user_id:st,p_payload:{title:o,objective:o,source:'school-evidence-page',version:VERSION,pack_id:pack,competence_id:competence,competence_label:competenceText,verification_scope:'driver_competence',lifecycle:'unified_mission_v1'},p_mission_type:$('missionType').value});$('objective').value='';$('competenceSelect').value='';await load()}catch(e){setStatus('⚠️ '+errorText(e.message||e),'warn')}}async function load(){setStatus(t('Connessione al server…','Connecting to server…','Konnessjoni mas-server…'));try{const[a,m]=await Promise.all([rpc('mdm_school_list_active_students',{}),rpc('mdm_school_evidence_list_missions',{p_student_user_id:null})]);if(a.authorized!==true||m.authorized!==true)throw new Error('school_not_authorized');renderStudents(Array.isArray(a.students)?a.students:[]);const ms=Array.isArray(m.missions)?m.missions:[];renderReviews(ms);renderMissions(ms);setStatus(t('Connesso. Dati aggiornati.','Connected. Data updated.','Konness. Data aġġornata.'),'ok')}catch(e){renderStudents([]);renderEmpty();setStatus('⚠️ '+errorText(e.message||e),'warn')}}$('backBtn').onclick=goBack;$('brandBtn').onclick=goBack;$('accountBtn').onclick=goBack;$('langBtn').onclick=()=>saveLang(lang()==='it'?'en':lang()==='en'?'mt':'it');$('assignBtn').onclick=assign;localize();renderEmpty();load()})();
